'AC25.4.1 EPIC-025'; from __future__ import annotations; from datetime import date; from decimal import Decimal; from typing import Any; from uuid import UUID; from sqlalchemy.ext.asyncio import AsyncSession; from src.audit import JournalEntrySourceType; from src.ledger import Account, AccountType, Direction, JournalEntry, JournalEntryStatus, JournalLine; from src.pricing.orm.market_data import FxRate; STANDARD_CHART_SPEC: tuple[tuple[str, AccountType], ...] = (('Cash', AccountType.ASSET), ('Credit Card', AccountType.LIABILITY), ('Owner Equity', AccountType.EQUITY), ('Salary', AccountType.INCOME), ('Dining', AccountType.EXPENSE))
async def build_standard_chart_of_accounts(db: AsyncSession, user_id: UUID, *, currency: str='SGD') -> list[Account]:
    accounts = [Account(user_id=user_id, name=name, type=acct_type, currency=currency) for name, acct_type in STANDARD_CHART_SPEC]; db.add_all(accounts); await db.commit()
    for account in accounts: await db.refresh(account)
    return accounts
def make_entry(user_id: UUID, entry_date: date, memo: str, lines: list[tuple], *, status: JournalEntryStatus=JournalEntryStatus.POSTED, source_type: JournalEntrySourceType=JournalEntrySourceType.MANUAL, tags: dict[str, Any] | None=None) -> JournalEntry:
    entry = JournalEntry(user_id=user_id, entry_date=entry_date, memo=memo, source_type=source_type, status=status); parsed_lines = []
    for item in lines: acc, direction, amt = (item[0], item[1], item[2]); curr = item[3] if len(item) > 3 else 'SGD'; fx = item[4] if len(item) > 4 else None; parsed_lines.append(JournalLine(account_id=acc.id, direction=direction, amount=Decimal(str(amt)), currency=curr, fx_rate=fx, tags=tags))
    entry.lines = parsed_lines; return entry
make_pair_entry = lambda user_id, entry_date, memo, debit_account, credit_account, amount, *, currency='SGD', fx_rate=None, source_type=JournalEntrySourceType.MANUAL, tags=None: make_entry(user_id, entry_date, memo, [(debit_account, Direction.DEBIT, amount, currency, fx_rate), (credit_account, Direction.CREDIT, amount, currency, fx_rate)], source_type=source_type, tags=tags)
async def seed_fx_rates(db: AsyncSession, *rates: tuple[str, str, Decimal | str, date]) -> list[FxRate]: models = [FxRate(base_currency=b, quote_currency=q, rate=Decimal(str(r)), rate_date=d, source='test') for b, q, r, d in rates]; db.add_all(models); await db.commit(); return models
